  CARD.replace("    def add_score(self, name, score):\n", "    def add_score(self, name, score):\n        if not 0 <= score <= 100:\n            raise ValueError(f'bad score {score}')\n") + "\ncard = Scorecard()\ncard.add_score('web-01', 88)\ntry:\n    card.add_score('web-01', 140)\nexcept ValueError as e:\n    print(e)\nprint(card.hosts['web-01'].scores)",
  "if not 0 <= score <= 100:\n    raise ValueError(f'bad score {score}')",
